import ipaddress, socket
from urllib.parse import urlparse

MAX_BYTES = 5120

def _public(host):
    for info in socket.getaddrinfo(host, 443, proto=socket.IPPROTO_TCP):
        ip = ipaddress.ip_address(info[4][0])
        if ip.is_private or ip.is_link_local or ip.is_loopback or ip.is_reserved:
            return False
    return True

async def resolve_client(db, http, static, client_id, redirect_uri):
    if client_id.startswith('https://'):
        u = urlparse(client_id)
        if not _public(u.hostname):
            raise InvalidClient('blocked address')
        r = await http.get(client_id, timeout=3, follow_redirects=False)
        if len(r.content) > MAX_BYTES:
            raise InvalidClient('too large')
        doc = r.json()
        if doc.get('client_id') != client_id:
            raise InvalidClient('id mismatch')
        uris, kind = doc.get('redirect_uris', []), 'cimd'
    else:
        row = await db.fetchrow('select redirect_uris, kind, status from oauth_client where client_id=$1', client_id)
        row = row or static.get(client_id)
        if not row or row['status'] != 'active':
            raise InvalidClient('unknown client')
        uris, kind = row['redirect_uris'], row['kind']
    if redirect_uri not in uris:        # exact match, no prefixes
        raise InvalidClient('redirect not listed')
    return ClientRecord(client_id, kind, uris)

