import hashlib, base64, hmac, jwt

RESOURCE = os.environ['MCP_RESOURCE_URL']
ISSUER = os.environ['OIDC_ISSUER_URL']
SKEW = 30

def s256(verifier: str) -> str:
    d = hashlib.sha256(verifier.encode('ascii')).digest()
    return base64.urlsafe_b64encode(d).rstrip(b'=').decode()

def pkce_ok(stored_challenge: str, verifier: str) -> bool:
    return hmac.compare_digest(s256(verifier), stored_challenge)

def verify_bearer(header, jwks):
    if not header or not header.startswith('Bearer '):
        raise Unauthorized()
    token = header[7:]
    kid = jwt.get_unverified_header(token).get('kid')
    key = jwks.get(kid)                      # refetches once on unknown kid
    claims = jwt.decode(
        token, key, algorithms=['ES256', 'RS256'],
        audience=RESOURCE, issuer=ISSUER, leeway=SKEW,
        options={'require': ['exp', 'aud', 'iss', 'sub']})
    if 'brain.read' not in claims.get('scope', '').split():
        raise Unauthorized()
    return Principal(claims['sub'], claims.get('tenant_id'))

